// build_wiki.js —— 从「直观版.html」提取条目数据，生成 wiki 版
// 用法：node build_wiki.js   （可重复运行，会覆盖 DB_START/DB_END 之间的数据块）
const fs = require("fs");
const path = require("path");
const vm = require("vm");
const dir = __dirname;

const src = fs.readFileSync(path.join(dir, "脑机接口功能想象_直观版.html"), "utf8");
const m = src.match(/const DATA=(\[[\s\S]*?\n\]);/);
if (!m) throw new Error("未找到 DATA 数组");
const items = vm.runInNewContext(m[1]);
if (!Array.isArray(items) || items.length !== 67) throw new Error("条目数异常：" + (items && items.length));

// ---------- 主题分组：组内互为「参见」 ----------
