  { key: "upload",    name: "意识上传 · 数字永生", desc: "把心智复制或转移到非生物基底，以及由此引出的同一性问题。七种作品立场全部集中在 L4，分歧在哲学而不在工程。", ids: "C09 C10 C11 C13 C14 C15 C20 M11 M12 X04 X06 X09 X10 X11 X12 X13 X14 X15" },
  { key: "immersion", name: "全感官沉浸 · 虚拟世界", desc: "用模拟流顶替或叠加感官输入。硬连线插孔、培养舱全接管、非侵入 FullDive、纯外设头显走了四条不同路径。", ids: "C04 C05 C19 M01 M02 M17 M18 M21 X05 X16 X19 X23 X25" },
  { key: "write",     name: "写入 · 技能 / 记忆 / 信念", desc: "往脑里写内容，是全部想象中编解码缺口最大的一类：硬件通道数可以堆，但「往哪儿写」没有理论。", ids: "C16 M04 M07 M13 X18 X20 X21 X22" },
  { key: "security",  name: "神经安全 · 被入侵", desc: "接口一旦联网，攻击面就自动出现。本质上是联网植入式医疗器械的安全问题，也是全表最易实现的一类想象。", ids: "C06 C07 C08 C20 M06 M08 M09 X02 X07 X08" },
  { key: "read",      name: "读出 · 义体 / 替身", desc: "从脑里解码意图并驱动外部装置，现实里已有临床雏形（脑控机械臂、光标、语音合成）。", ids: "C01 C02 C03 C12 M03 M05 X01 X23 X24" },
  { key: "network",   name: "脑联网 · 群体意识", desc: "多个脑直连成网络，个体边界、同步机制与隐私是核心难题。", ids: "M19 X01 X03 X17" },
  { key: "rules",     name: "时间 · 物理规则操纵", desc: "主观时间加速与改写模拟规则，多数属叙事装置而非技术。注意与义体生理加速区分。", ids: "C03 M10 M15 M16 M20" },
  { key: "society",   name: "副作用 · 商业与伦理", desc: "成瘾、人格解体、付费来世、数字人格权利——技术之外的代价，常比技术设定更锋利。", ids: "C05 C11 C17 C18 M14 X10 X11 X14" }
