// ---------- 术语表 ----------
const GLOSSARY = [
  { key: "engram", term: "engram 印迹", aliases: ["印迹", "Engram"], def: "把一个人的记忆、言语模式与行为倾向数字化后的副本。《赛博朋克 2077》明确设定它没有主体意识、会随时间劣化——这正是 Soulkiller 这个名字的反讽所在。", ids: "C10 C11 C13 C20 X06" },
  { key: "soulkiller", term: "Soulkiller 灵魂杀手", aliases: ["灵魂杀手", "Soulkiller"], def: "Alt Cunningham 于 2013 年编写的程序：扫描并复制心智进网络，同时摧毁原生大脑。它是「方法」，Relic 是载体，Mikoshi 是存放地，三者常被混为一谈。", ids: "C09 C15 C20" },
  { key: "relic", term: "Relic 生物芯片", aliases: ["Relic", "生物芯片"], def: "荒坂的可植入生物芯片，存储 engram 并可写入宿主神经系统；原型还能用纳米技术修复脑损伤、并逐步覆写宿主人格。不只是硬盘，还是主动写入装置。", ids: "C11 C12 C13 C16" },
  { key: "mikoshi", term: "Mikoshi 神舆", aliases: ["神舆", "Mikoshi"], def: "荒坂存放 engram 的服务器 / 数字监狱，Alt 曾被囚于此。存储数据不难，难的是硬盘里那个「人」。", ids: "C14 C15 C09" },
  { key: "blackwall", term: "Blackwall 黑墙", aliases: ["黑墙", "Blackwall"], def: "隔离旧网中失控 AI 的防火墙。作为网络隔离 / air-gap 工程上平凡；「墙后 AI 会吞噬人脑」是设定。", ids: "C07 C15 C20" },
  { key: "braindance", term: "Braindance 超梦", aliases: ["超梦", "Braindance"], def: "录制并回放他人完整第一人称感官 + 情绪 + 生理状态，可剪辑、多视角。祖型是《神经漫游者》的 Simstim（实时直播版）。", ids: "C04 C05 C19 X05 X16" },
  { key: "quickhack", term: "Quickhack 快速破解", aliases: ["快速破解", "Quickhack"], def: "网络行者无线入侵他人神经义体。本质是联网植入式设备的安全攻防，是全表里最可能被先验证的想象。桌游时代反而必须用缆线直连。", ids: "C06 C08 X02 X07" },
  { key: "neurolink", term: "神经接口 Neural Link", aliases: ["Neural Link", "神经接口"], def: "颈后 / 头部插槽，所有义体的通用中枢总线。现实中不存在跨厂商通用插槽，每个植入体都是专用系统。", ids: "C01 C02 M01" },
  { key: "cyberpsycho", term: "赛博精神病", aliases: ["赛博精神病", "Cyberpsychosis"], def: "义体过载导致人格解体与暴力倾向。属叙事 / 社会学装置，不是技术实现目标，用来给义体容量上代价。", ids: "C17 C18 C19" },
  { key: "matrix", term: "Matrix 矩阵", aliases: ["矩阵", "Matrix"], def: "机器建造的全感官模拟，顶替人的全部感官输入并接管运动输出。核心不是「接口」，是「替代」。", ids: "M01 M02 M14 M17 M21" },
  { key: "rsi", term: "残余自我影像 RSI", aliases: ["RSI", "残余自我影像"], def: "人在 Matrix 里的形象由「自我形象」字段决定，与真实肉体不同。解释了拔除后 Neo 秃头苍白、Matrix 里却有头发。", ids: "M03" },
  { key: "construct", term: "Construct 构造体", aliases: ["构造体", "Construct"], def: "空白白色训练空间，可加载技能程序（I know Kung Fu）。现实运动技能靠反复练习，无「写入复杂动作程序」的理论。", ids: "M04 M18 X18" },
  { key: "redpill", term: "红药丸 / 蓝药丸", aliases: ["红药丸", "蓝药丸"], def: "其实是两个操作：中断追踪程序并唤醒（易），以及抹掉记忆、植入替代人生（极难）。常被误当成「吃颗药」。", ids: "M07 M13 M06" },
  { key: "cyberbrain", term: "电子脑 Cyberbrain / Ghost", aliases: ["电子脑", "Cyberbrain", "Ghost"], def: "《攻壳机动队》里大脑直接联网、全身义体化；Ghost 是区别于数据的自我，引出「换完身体我还是我吗」的连续性问题。", ids: "X01 X02 X03 X04" },
  { key: "cortical", term: "皮质栈 / DHF", aliases: ["皮质栈", "DHF"], def: "《碳变》里颈后植入存储完整人格，换体如换衣，栈被毁才是「真死」。设定默认「复制＝本人」，比 CP2077 武断。", ids: "X09" },
  { key: "cookie", term: "Cookie 意识副本", aliases: ["cookie", "Cookie"], def: "《黑镜》里扫描出有完整主观体验的副本，可被奴役、可被加速承受「百年孤独」——数字人格权利问题的核心设定。", ids: "X10 X11 X14" },
  { key: "fulldive", term: "FullDive 全潜行", aliases: ["FullDive", "NERvGear"], def: "《刀剑神域》的非侵入头盔读脑 + 阻断本体感觉 + 全感官写入。最大虚构点：无创设备达到侵入式全带宽。", ids: "X16 X15" },
  { key: "wbe", term: "全脑仿真 / 意识上传", aliases: ["全脑仿真", "意识上传", "WBE"], def: "按突触级扫描并模拟全脑。2025 年《State of Brain Emulation Report》定为 TRL 1–2、至少 30–40 年；另有基底依赖与副本问题。", ids: "C09 M12 X12 X13 X14" },
  { key: "bandwidth", term: "带宽瓶颈", aliases: ["带宽瓶颈", "带宽"], def: "语音约 39 bit/s；顶尖植入 1024 电极对约 860 亿神经元。这是所有「全沉浸」想象最硬的一堵墙。", ids: "C04 M01 M02 X16 X25" },
  { key: "bidirectional", term: "双向 BCI / 写入", aliases: ["双向 BCI", "全双工"], def: "现实人体植入目前以只读为主，刺激（写入）刚进小规模试验，且不知道往哪儿写。虚构几乎都假设全双工随意写。", ids: "C02 C06 M04 X19 X23" },
  { key: "copy", term: "副本问题 / 主体连续性", aliases: ["副本问题", "延续性谬误", "主体连续性"], def: "复制一个行为完全相同但无主观体验的东西，算不算让你活下去？CP2077 与《SOMA》回答「不算」，《碳变》《万神殿》默认「算」。", ids: "C10 C13 M11 M12 X09 X10 X12 X13" },
  { key: "substrate", term: "基底依赖", aliases: ["基底依赖", "基底"], def: "意识是否只能由生物组织产生。若成立，数字上传只会得到功能模仿品而非有体验的主体；目前无实证判据。", ids: "C10 X12 X14 M11" }
];

