const HOTSETS = [["HOT", HOT], ["HOT2A", HOT2A], ["HOT2B", HOT2B], ["HOT2C", HOT2C], ["HOT2D", HOT2D], ["HOT2E", HOT2E], ["HOT2F", HOT2F], ["HOT2G", HOT2G], ["HOT2H", HOT2H], ["HOT2I", HOT2I]];
const KEYSET = new Set();
HOTSETS.forEach(([sn, arr]) => arr.forEach(h => {
  if (KEYSET.has(h.key)) throw new Error(sn + " key 重复：" + h.key);
  KEYSET.add(h.key);
  h.ids.split(" ").filter(Boolean).forEach(id => { if (!IDSET.has(id)) throw new Error(sn + "[" + h.key + "] 条目不存在：" + id); });
  h.cks.split(" ").filter(Boolean).forEach(k => { if (!CKSET.has(k)) throw new Error(sn + "[" + h.key + "] 术语不存在：" + k); });
  if (sn !== "HOT" && !CATS[h.cat]) throw new Error(sn + "[" + h.key + "] cat 非法：" + h.cat);
  (h.core || []).forEach(c => { if (!LVMAPTEST(c.lv)) throw new Error(sn + "[" + h.key + "] 难度非法：" + c.lv); });
  if (!Array.isArray(h.core) || !h.core.length) throw new Error(sn + "[" + h.key + "] core 为空");
  ["hot", "profile", "real", "vs"].forEach(f => { if (!h[f]) throw new Error(sn + "[" + h.key + "] 缺字段：" + f); });
  if (!Array.isArray(h.scenes) || !h.scenes.length) throw new Error(sn + "[" + h.key + "] scenes 为空");
}));
function LVMAPTEST(lv) { return ["L1","L2","L3","L4","L5","Ln"].indexOf(lv) !== -1; }

