const LAW_LEVELS = [
  { k: "V0", name: "合法", c: "#16a34a", judged: true,
    def: "现行法无禁止性规定，也不侵害他人法益。可以直接做，不需要许可。" },
  { k: "V1", name: "合规可行", c: "#0891b2", judged: true,
    def: "现行法允许，但须满足许可、审批、资质或有效同意等要件。不办手续即转为违法——这是「有条件的合法」，不是「默认合法」。" },
  { k: "V2", name: "违法", c: "#dc2626", judged: true,
    def: "现行法有明确禁止性规定或有对应罪名。做了就是违法或犯罪；且同意通常不能作为抗辩（人格权不得放弃、生命不可处分）。" },
  { k: "V3", name: "无规定", c: "#ca8a04", judged: false,
    def: "现行法既未允许也未禁止，缺可适用的规则。本表不作判断。注意：这不等于「合法」——刑事上法无明文不为罪（刑法第3条），民事上却意味着受害者无从主张。" },
  { k: "V4", name: "不进入评价", c: "#6b7280", judged: false,
    def: "行为、主体或后果在法律上无法构成评价对象（物理不可能、无行为主体、纯游戏机制，或本身不是法律行为的社会现象）。本表明确不作判断，也不宜标为合法或违法。" }
];

// 每条：j=法律议题（1–3 个）、v=法律状态、basis=现行法依据、why=一句话判词
// v>=3 的条目，why 必须说明「为什么不判断」，不允许暗中给出结论
const LAW = {
  "C01": { j: ["J4", "J3"], v: 1, basis: "《医疗器械监督管理条例》第三类器械注册；《民法典》第1008条；NMPA 注册与 FDA IDE 路径", why: "植入式脑机接口已有现成审批轨道，合法性全部系于两点：是否取得注册、是否完成知情同意——与技术水平无关。" },
  "C02": { j: ["J4", "J5"], v: 1, basis: "《医疗器械监督管理条例》；《产品质量法》；《广告法》第17条（非医疗器械不得宣称医疗功效）", why: "修复型义体按医疗器械管理，路径清晰；一旦跨到「超常感知」，就不再属于医疗器械定义范围，只能作为普通产品承担责任。" },
  "C03": { j: ["J4", "J5", "J1"], v: 3, basis: "《医疗器械监督管理条例》第二条（医疗器械限于疾病的诊断、预防、监护、治疗或缓解）", why: "不作判断，因为无门可进：增强型神经加速器不是医疗器械，拿不到注册，也不宜作为普通商品植入人体。现行法既未禁止也未许可。造成他人损害仍按《民法典》侵权责任编处理。" },
  "C04": { j: ["J3", "J2", "J7"], v: 1, basis: "《个人信息保护法》第28–29条（敏感个人信息单独同意）；《民法典》第1019、1023条；《刑法》第363–364条；《互联网信息服务深度合成管理规定》", why: "技术本身合法。合规点有三个：录制他人体验须单独同意、内容不得涉淫秽、合成内容须标识。任一条不满足，即从合法转为违法。" },
  "C05": { j: ["J5", "J1", "J7"], v: 3, basis: "《未成年人保护法》网络保护专章；《消费者权益保护法》第18条；《民法典》第1183条", why: "不作判断，因为无对应规则：「成瘾性设计」在现行法上没有独立的责任类型，只能借道未成年人保护与消保；「意识混淆」的损害也无法在伤残分级中评定。" },
  "C06": { j: ["J7", "J6", "J1"], v: 2, basis: "《刑法》第285条（非法获取计算机信息系统数据、非法控制计算机信息系统）、第286条；美国 CFAA 18 U.S.C. §1030；英国 Computer Misuse Act 1990", why: "全表定性最清楚的一条。未授权入侵并控制他人植入式医疗设备，在主要法域一律构成犯罪；致人伤亡的，与故意伤害、故意杀人想象竞合，从一重处断。" },
  "C07": { j: ["J6", "J5"], v: 1, basis: "《网络安全法》第21、31、59条；《关键信息基础设施安全保护条例》", why: "隔离不是限制，是义务：运营者未履行关基保护义务才违法。这条在法律上没有争议。" },
  "C08": { j: ["J7", "J1", "J6"], v: 2, basis: "《刑法》第232、234条、第20条（正当防卫要件）；《日内瓦公约第一附加议定书》第36条", why: "部署会自动致死的反制程序，在任何法域都构成故意杀人或危害公共安全。正当防卫要求针对正在进行的不法侵害且不过当，自动致死装置两个要件都不满足。" },
  "C09": { j: ["J7", "J1", "J2"], v: 2, basis: "《刑法》第232条（故意杀人）；《民法典》第13、1002条", why: "法律不需要先回答「engram 是不是人」——摧毁原脑这一行为本身就构成故意杀人。伦理上的 E4 死结，在刑法上是常规案件，这是两个维度最锋利的分野。" },
  "C10": { j: ["J3", "J2"], v: 3, basis: "《个人信息保护法》第28条；《民法典》第13、992条", why: "不作判断：扫描并留存本身可依有效同意合法，但「engram 是数据还是人」无规定，故其处分、继承、删除全部无法可依——不是违法，是无人能主张权利。" },
  "C11": { j: ["J2", "J5", "J3"], v: 3, basis: "《民法典》第992条（人格权不得放弃、转让、继承）、第994条；《个人信息保护法》第49条", why: "不作判断，因为合同标的不存在：人格权不得放弃与继承，生前合同无法处分死后「人格」。近亲属只能主张死者人格利益，不能替死者续命。" },
  "C12": { j: ["J1", "J2", "J7"], v: 3, basis: "《民法典》第46–53条（宣告死亡与撤销）；《人体器官移植条例》；脑死亡与心肺死亡标准并存", why: "不作判断：「生物学死亡后恢复意识」在现行法上不存在。一旦发生，身份、婚姻（第51条）、财产要全部重算，而法条没有对应机制，只能类推适用撤销死亡宣告。" },
  "C13": { j: ["J1", "J7", "J2"], v: 2, basis: "《刑法》第232、234条；《民法典》第992条、第143条", why: "未经同意覆写他人人格，构成故意伤害（器质性精神障碍可评伤残），严重者按杀人论。即使本人同意也无效——人格权不得放弃，同意在此不是抗辩。" },
  "C14": { j: ["J3", "J2", "J5"], v: 3, basis: "《数据安全法》分类分级；《个人信息保护法》第21条（委托处理）；《网络安全法》第37条", why: "不作判断：托管神经数据触及分级与出境规则，但「托管的是人格」没有对应制度。托管合同只能按数据存储服务处理，无法约束「删除即终止人格存续」。" },
  "C15": { j: ["J2", "J7", "J6"], v: 3, basis: "《民法典》第13条、第2条（民事主体限于自然人、法人、非法人组织）", why: "不作判断，但答案是否定性的：以 AI 形态存续的实体只能是数据，不享人格权，也谈不上「被杀」。数据层面的财产归属与删除规则，则无专门规定。" },
  "C16": { j: ["J4", "J5"], v: 1, basis: "《医疗器械监督管理条例》；《民法典》第1219条（患者知情同意与选择权）", why: "可摘除意味着退出权真正可行使，符合患者自主与器械可及性要求；剩下的只是「增强适应证」的注册类别问题。" },
  "C17": { j: ["J1", "J7", "J5"], v: 3, basis: "《精神卫生法》第30条；《刑法》第18条（责任能力鉴定）；ICD-11 / DSM-5-TR 无此诊断", why: "不作判断：没有对应诊断，就不能作为责任能力抗辩依据。若由产品缺陷导致走产品责任；若被用于就业与保险排斥，落入反歧视与自动化决策规制。" },
  "C18": { j: ["J2", "J3", "J6"], v: 2, basis: "《个人信息保护法》第24条（自动化决策不得实行不合理差别待遇）；《就业促进法》第3、30条", why: "把人量化成可排序的「人性值」并用于准入，直接违反自动化决策与反歧视规定。作为游戏机制则无法律意义（属 V4 情形）。" },
  "C19": { j: ["J5", "J1"], v: 0, basis: "《消费者权益保护法》；《广告法》；民间借贷利率上限（LPR 四倍）", why: "现行法不禁止高风险自费医疗消费。但若涉诱导性放贷、虚假宣传、向无偿还能力者营销，则分别落入非法放贷、广告法与消保法。" },
  "C20": { j: ["J6", "J7", "J1"], v: 2, basis: "《刑法》第232、234条；《罗马规约》第7条（反人类罪）；《出口管制法》", why: "不论由谁采购，「抹除人格」落地都是杀害或故意伤害；国家层面的系统性行为可能触及反人类罪。但现行军控条约未列名，约束来自人权法与国内刑法，不来自军控。" },
  "M01": { j: ["J4", "J3"], v: 1, basis: "《医疗器械监督管理条例》；《个人信息保护法》第28条", why: "接口是纯器械与数据问题，现行法完全覆盖；关键在注册类别与术后数据流向。" },
  "M02": { j: ["J1", "J7", "J2"], v: 2, basis: "《刑法》第238条（非法拘禁）、第234条；《民法典》第1003条（身体权）", why: "剥夺人身自由并占有身体，构成非法拘禁与故意伤害。「从未同意」不影响违法性，只影响监护责任与量刑。" },
  "M03": { j: ["J2", "J5"], v: 1, basis: "《民法典》第1019条（禁止伪造肖像）、第1024条（名誉权）、第1034条（个人信息）", why: "自主设定的数字形象受肖像权保护；技术本身合规，但平台单方改参数即构成侵权，用户可要求停止侵害与赔偿。" },
  "M04": { j: ["J4", "J5", "J8"], v: 3, basis: "《医疗器械监督管理条例》；《执业医师法》《道路交通安全法》（资质要求）；《著作权法》", why: "不作判断：技能作为数据可受著作权保护，但「植入人体形成能力」无审批类别。更硬的一条是资质法规——持证要求不因技能真实而豁免，下载完也不能行医或驾驶。" },
  "M05": { j: ["J3", "J1"], v: 1, basis: "《个人信息保护法》第13条（履行合同所必需）、第51条（权限最小化）；《刑法》第253条之一、第285条", why: "职务范围内的授权访问合法，越权读取即构成侵犯公民个人信息罪或非法获取计算机信息系统数据罪。分界线是权限与日志，不是技术能力。" },
  "M06": { j: ["J6", "J5"], v: 1, basis: "《网络安全法》第21条（等级保护）；《电信条例》", why: "单点通道属网络可靠性与接入管理问题，现行法有明确要求；运营者未尽保障义务致损，按违约与侵权处理。" },
  "M07": { j: ["J2", "J7"], v: 3, basis: "《宪法》第35、36条（言论与信仰自由）；《民法典》第990条（一般人格权）", why: "不作判断：现行法只约束「外部干预」，不处理「强制改变他人对现实的认知」。无对应罪名，也无成熟侵权类型，造成精神损害只能走一般人格权。" },
  "M08": { j: ["J7", "J1", "J5"], v: 3, basis: "《刑法》第233条（过失致人死亡）；《民法典》第1198条（安全保障义务）、第1202条（产品责任）", why: "不作判断：「虚拟事件导致生理死亡」的因果关系在医学与法学上都没有标准；注意义务在内容方、平台、设备商之间如何分配，现行法没有规则。" },
  "M09": { j: ["J7", "J1"], v: 3, basis: "《刑法》第18条（责任能力）、第28条（胁从犯）；间接正犯理论", why: "不作判断：施害方若为人，可按间接正犯追究、被控者无罪；但施害方是非人程序时没有刑事责任主体。漏洞不在定性，在「没有被告」。" },
  "M10": { j: ["J1"], v: 4, basis: "—（无对应行为类型）", why: "不判断：主观时间感知加速不改变客观物理过程，「躲子弹」在物理上不可能，法律不评价不可能之事。若仅指感知加速本身，按 C03 处理。" },
  "M11": { j: ["J2", "J8"], v: 3, basis: "《民法典》第2、13条（主体范围）；《刑法》第275条（故意毁坏财物）；《著作权法》", why: "不作判断：程序不具民事主体资格，故「不被删除权」的现行法答案是「没有」；删除按数据或财产处理，可能构成毁坏财物，但不构成杀人。" },
  "M12": { j: ["J2"], v: 4, basis: "—（无对应行为类型）", why: "不判断：「重构」在物理上没有对应过程，法律无从假设。即使是复制，现行法只处理原件的死亡，复制件不产生新的权利主体。" },
  "M13": { j: ["J2", "J3", "J7"], v: 3, basis: "《宪法》第35、36条；《民法典》第990条；无对应罪名", why: "不作判断：信念被强制改写，现行法找不到可评价的行为类型——思想自由只约束外部干预，而「写入」发生在内部。既无罪名，也无侵权案由。" },
  "M14": { j: ["J7", "J2"], v: 2, basis: "《刑法》第244条（强迫劳动）；美国 18 U.S.C. §1581（奴役）；ICCPR 第8条", why: "奴役与强迫劳动在主要法域都是重罪。L5 是技术难度，不是法律难度——技术上做不到，不影响法律上的定性。" },
  "M15": { j: ["J2"], v: 4, basis: "—（无对应行为类型）", why: "不判断：纯感知设定，没有外部行为，也没有法益侵害对象；法律不评价「看到什么」。" },
  "M16": { j: ["J1", "J5"], v: 0, basis: "《民法典》第1219条（患者选择权）；《消费者权益保护法》第9条（自主选择）", why: "自主退出在医疗与消费两端都受支持；若运营方阻碍退出，反而构成非法拘禁。全表唯一一条法律明确站在用户一侧的。" },
  "M17": { j: ["J7", "J1"], v: 2, basis: "《刑法》第234、238条", why: "对「看见系统异常」的人施加惩罚，构成故意伤害或非法拘禁，无任何免责事由——「他知道了不该知道的」不是抗辩。" },
  "M18": { j: ["J5", "J2"], v: 1, basis: "《消费者权益保护法》第8、20条；《民法典》第148条（欺诈）", why: "训练程序本身合法；但若「选择权」是设计好的假选择，构成欺诈与知情权侵害，可依第148条撤销并索赔。" },
  "M19": { j: ["J8", "J2"], v: 3, basis: "《民法典》第2、13条；《刑法》第275条；无「机器权利」规范", why: "不作判断：现行法只保护人的意志自由，AI 无意志自由可侵；若该智能体有财产价值，单方改造可能构成毁坏财物——但「改造它的价值观」本身不是可诉行为。" },
  "M20": { j: ["J2"], v: 4, basis: "—（纯游戏机制）", why: "不判断：游戏机制不产生现实法律效果，不进入评价。" },
  "M21": { j: ["J4", "J3"], v: 1, basis: "《民法典》第1219条；《个人信息保护法》第14条（同意须重新取得）", why: "自愿回归的同意链条清晰，只需重新履行告知与器械随访义务；关键是旧同意不能覆盖新风险。" },
  "M22": { j: ["J3", "J1"], v: 1, basis: "《刑事诉讼法》第52、150条；《个人信息保护法》第13条", why: "取证行为受刑诉法与个保法双重约束；神经数据能否作证据，取决于取证程序是否合法，而不取决于它是不是「脑数据」。" },
  "X01": { j: ["J2", "J4"], v: 3, basis: "《民法典》第13条；《医疗器械监督管理条例》", why: "不作判断：电子脑作为器械可以注册，义体化的人只要脑未死亡仍是自然人；但 Ghost 被复制后不产生新主体，复制件的地位无规定。" },
  "X02": { j: ["J7", "J3"], v: 2, basis: "《刑法》第285、286、234条；《民法典》第1183条", why: "未授权入侵并改写他人神经数据，构成非法控制计算机信息系统罪；造成持久精神障碍的，可按故意伤害（致人重伤）评价。" },
  "X03": { j: ["J7"], v: 4, basis: "《刑法》第25条（共同犯罪须有共同故意）", why: "不判断：「没有主谋」在刑法上不是难题，只是不成立共同犯罪，各人对自己行为独立负责。现象本身不是法律行为。" },
  "X04": { j: ["J2"], v: 3, basis: "《民法典》第13、46条", why: "不作判断：没有「人格融合」的法律类型。若视为两个自然人合并，身份、婚姻、财产全部要重算，而现行法只能按「一方死亡」处理，融合并不是死亡。" },
  "X05": { j: ["J3", "J2"], v: 1, basis: "《个人信息保护法》第14、15条（同意可撤回、范围变更须重新取得）；《民法典》第1019条", why: "录播的同意链条比互动清晰；合规重点是撤回机制与二次利用限制——原同意不覆盖新用途。" },
  "X06": { j: ["J2", "J8"], v: 3, basis: "《著作权法》第22条（署名权、修改权、保护作品完整权的保护期不受限制）；《民法典》第13条", why: "不作判断：副本非主体，被当工具不构成奴役；但若它承载作者的著作人格权，第22条是现行法上唯一可用于保护「数字作者」的条款——保护期不受限制，恰好在作者死后仍有效。" },
  "X07": { j: ["J7", "J1"], v: 2, basis: "《刑法》第232、234、286条", why: "与 C08 同构：致死性反制程序等同于预设的杀人装置，不因写在代码里而改变性质。" },
  "X08": { j: ["J6", "J7", "J3"], v: 2, basis: "《刑法》第286条（破坏计算机信息系统）、第232、234条", why: "传播破坏性程序即构成破坏计算机信息系统罪；若同时作用于神经植入物致人伤亡，按想象竞合从一重处断。「语义病毒」的称呼不改变定性。" },
  "X09": { j: ["J2", "J4", "J5"], v: 3, basis: "《民法典》第13条；《医疗器械监督管理条例》；《人体器官移植条例》", why: "不作判断：换体手术作为医疗行为可合规，但「哪具身体是本人」决定身份、婚姻、财产与刑事责任归属；现行法以生物身体同一性为基础，无跨体同一性规则。" },
  "X10": { j: ["J2", "J7"], v: 3, basis: "《刑法》第232、234、248条；《民法典》第13条", why: "不作判断：副本非人，故不构成杀人或虐待；但若承认其感受能力，现行法没有任何罪名可用。这是「合法但不正当」的典型——法律的沉默不等于允许。" },
  "X11": { j: ["J2", "J5", "J3"], v: 3, basis: "《民法典》第994条（死者人格利益由近亲属主张）；《个人信息保护法》第49条", why: "不作判断：服务合同有效（标的是数据处理），但「停止付费即终止人格存续」无法被约束；死者人格利益只能由近亲属主张，超出范围即无人可诉。" },
  "X12": { j: ["J2", "J4"], v: 3, basis: "《民法典》第13条；《医疗器械监督管理条例》；产品责任规则", why: "不作判断：复制件不是原主，原主的死亡仍按死亡处理；复制件致害由谁承担无规定，实务上只能落到制造者的产品责任与运营者的雇主责任。" },
  "X13": { j: ["J4", "J5", "J2"], v: 1, basis: "《民法典》第1008、1219条；《涉及人的生命科学和医学研究伦理审查办法》(2023)", why: "扫描与建模属医疗行为，须伦理审查、书面同意与器械审批；「上传后的身份」无规定，但这一段实施本身是合规可行的。" },
  "X14": { j: ["J2", "J7"], v: 3, basis: "《刑法》第232条；《民法典》第13条", why: "不作判断：若 host 是人，反复杀死构成故意杀人；若不是，只是设备测试。全部判定系于「是不是人」，而这一步现行法没有标准——法律把难题原样退回。" },
  "X15": { j: ["J2", "J3"], v: 3, basis: "《民法典》第13条；《个人信息保护法》第28条", why: "不作判断：与 X01 同构——灵魂被翻译成数据后，编辑权只能按个人信息处理规则行使；「编辑后的人还是不是原来的人」无规定。" },
  "X16": { j: ["J1", "J7", "J5"], v: 1, basis: "《产品质量法》；《消费者权益保护法》第18条；《刑法》第238条", why: "全潜行设备作为消费电子须通过安全认证，技术本身合规；但运营方限制登出即构成非法拘禁，致死按故意杀人或过失致人死亡。" },
  "X17": { j: ["J7", "J2", "J6"], v: 2, basis: "《刑事诉讼法》第12条（未经人民法院依法判决，对任何人不得确定有罪）；《宪法》第131条", why: "定罪量刑权专属人民法院，任何算法系统不得直接认定有罪；作为侦查辅助工具时其输出只是线索，必须经法庭质证——直接采信即违法。" },
  "X18": { j: ["J4", "J5", "J8"], v: 3, basis: "《医疗器械监督管理条例》第二条；《专利法》第25条", why: "不作判断：植入式神经模块属第三类器械须注册，但「人格模块」不属治疗用途，拿不到适应证。技术上可做，监管上无门。" },
  "X19": { j: ["J5", "J1", "J3"], v: 1, basis: "《民法典》第1198条（安全保障义务）；《消费者权益保护法》第18条", why: "属消费类神经刺激设备，须符合产品安全与警示义务；「用户点了同意」不免除经营者的安全保障义务，娱乐不是豁免理由。" },
  "X20": { j: ["J2", "J3", "J7"], v: 3, basis: "《民法典》第147条（重大误解）、第148条（欺诈）；无对应罪名", why: "不作判断：没有「侵犯思想」的罪名或侵权类型。若植入导致财产处分，可依意思表示不真实撤销，但受害者既不知情也无法举证——救济写在纸上，实际不可用。" },
  "X21": { j: ["J2", "J3"], v: 3, basis: "《民法典》第994条；《人体器官移植条例》；《殡葬管理条例》", why: "不作判断：死者不享人格权，近亲属可主张死者人格利益；但「记忆」是否属于遗体的一部分没有规定——若算遗体，处理规则完全不同。" },
  "X22": { j: ["J3", "J7"], v: 1, basis: "《刑事诉讼法》第150条（技术侦查须批准）、第56条（非法证据排除）；《个人信息保护法》第13条", why: "只能作为法定技术侦查措施使用并接受司法审查；未经批准取得即属非法证据应予排除。直接采信等于让人为自己无法控制的心理内容负责。" },
  "X23": { j: ["J7", "J5", "J1"], v: 1, basis: "《民法典》第1165条（过错责任）、第1202条（产品责任）", why: "远程操作致害，操作者是行为人，制造商按产品责任承担，网络服务商按过错承担——现行法完全能处理，只需固定「操作者—设备—网络」三层证据。" },
  "X24": { j: ["J3", "J5", "J2"], v: 1, basis: "《个人信息保护法》第28条（情绪识别属敏感个人信息）；EU AI Act 第5(1)(b)；《广告法》第28条", why: "读取侧须单独同意，说服侧本身不禁止；一旦构成「实质性扭曲行为」，在欧盟直接违法，在中国按虚假广告与消保法处理——同一行为跨境定性不同。" },
  "X25": { j: ["J5", "J8"], v: 1, basis: "《消费者权益保护法》；《网络安全法》；《著作权法》", why: "纯外设，按消费电子与平台治理处理；是全表法律负担最轻的完整沉浸方案——不碰脑，就绕开了绝大多数神经相关的规制。" }
};

// 校验：覆盖完整、议题与等级合法、不判断项必须明说
items.forEach(d => { if (!LAW[d.id]) throw new Error("缺少法律标注：" + d.id); });
Object.keys(LAW).forEach(id => {
  if (!IDSET.has(id)) throw new Error("LAW 条目不存在：" + id);
  const r = LAW[id];
  if (!Array.isArray(r.j) || !r.j.length || r.j.length > 3) throw new Error(id + " 法律议题数量应为 1–3");
  r.j.forEach(k => { if (!LAW_DIMS.some(x => x.k === k)) throw new Error(id + " 法律议题非法：" + k); });
  if ([0, 1, 2, 3, 4].indexOf(r.v) === -1) throw new Error(id + " 法律状态非法：" + r.v);
  if (!r.basis) throw new Error(id + " 缺 basis");
  if (!r.why) throw new Error(id + " 缺 why");
  if (r.v >= 3 && r.why.indexOf("不作判断") === -1 && r.why.indexOf("不判断") === -1)
    throw new Error(id + " 为 V" + r.v + "（不判断），why 必须显式说明为何不判断");
});

// ---------- 组装 ----------
const byId = {};
items.forEach(d => { byId[d.id] = d; });

const groupIds = GROUPS.map(g => ({ key: g.key, ids: g.ids.split(" ").filter(Boolean) }));
const seeOf = {};
groupIds.forEach(g => g.ids.forEach(id => {
  if (!seeOf[id]) seeOf[id] = new Set();
  g.ids.forEach(o => { if (o !== id) seeOf[id].add(o); });
}));
items.forEach(d => {
  d.see = [...(seeOf[d.id] || [])].sort().slice(0, 8);
  d.groups = groupIds.filter(g => g.ids.includes(d.id)).map(g => g.key);
});

WORKS.forEach(w => {
  w.ids = items.filter(d => {
    if (w.prefix) return d.id[0] === w.prefix;
    return (w.kw || []).some(k => d.work.indexOf(k) !== -1);
  }).map(d => d.id);
});

const missing = items.filter(d => !WORKS.some(w => w.ids.includes(d.id))).map(d => d.id);
if (missing.length) throw new Error("未被任何作品页收录：" + missing.join(" "));

// 把伦理标注挂到条目上，条目页直接读
items.forEach(d => {
  const r = ETH[d.id];
  d.eth = { n: r.n, e: r.e, why: r.why };
});

const ETH_DB = {
  dims: ETH_DIMS.map(x => ({ k: x.k, name: x.name, en: x.en, q: x.q, def: x.def, real: x.real, ids: items.filter(d => ETH[d.id].n.includes(x.k)).map(d => d.id) })),
  levels: ETH_LEVELS.map(x => ({ k: x.k, name: x.name, c: x.c, def: x.def, ids: items.filter(d => ETH[d.id].e === parseInt(x.k.slice(1), 10)).map(d => d.id) }))
};

// 难度 × 伦理 交叉矩阵：rows=L0..L5/Ln，cols=E0..E4
const LVK = ["L1","L2","L3","L4","L5","Ln"];
const MATRIX = LVK.map(lv => {
  const row = { lv: lv, cells: [0,0,0,0,0] };
  items.filter(d => (d.lv === -1 ? "Ln" : "L" + d.lv) === lv).forEach(d => { row.cells[ETH[d.id].e]++; });
  return row;
});

// 把法律标注挂到条目上
items.forEach(d => {
  const r = LAW[d.id];
  d.law = { j: r.j, v: r.v, basis: r.basis, why: r.why };
});

const LAW_DB = {
  dims: LAW_DIMS.map(x => ({ k: x.k, name: x.name, en: x.en, q: x.q, def: x.def, law: x.law, gap: x.gap, ids: items.filter(d => LAW[d.id].j.includes(x.k)).map(d => d.id) })),
  levels: LAW_LEVELS.map(x => ({ k: x.k, name: x.name, c: x.c, judged: x.judged, def: x.def, ids: items.filter(d => LAW[d.id].v === parseInt(x.k.slice(1), 10)).map(d => d.id) }))
};

// 难度 × 法律状态 交叉矩阵
const MATRIX_LAW = LVK.map(lv => {
  const row = { lv: lv, cells: [0,0,0,0,0] };
  items.filter(d => (d.lv === -1 ? "Ln" : "L" + d.lv) === lv).forEach(d => { row.cells[LAW[d.id].v]++; });
  return row;
});

const DB = {
  items: items,
  ethics: ETH_DB,
  matrix: MATRIX,
  law: LAW_DB,
  matrixLaw: MATRIX_LAW,

  groups: GROUPS.map(g => ({ key: g.key, name: g.name, desc: g.desc, ids: g.ids.split(" ").filter(Boolean) })),
  glossary: GLOSSARY.map(c => ({ key: c.key, term: c.term, aliases: c.aliases, def: c.def, ids: c.ids.split(" ").filter(Boolean) })),
  works: WORKS.map(w => ({ key: w.key, name: w.name, sub: w.sub, intro: w.intro, list: w.list, ids: w.ids })),
  hot: HOT.map(h => ({ key: h.key, name: h.name, sub: h.sub, deep: true, cat: "", hot: h.hot, profile: h.profile, core: h.core, scenes: h.scenes, real: h.real, vs: h.vs, ids: h.ids.split(" ").filter(Boolean), cks: h.cks.split(" ").filter(Boolean) })),
  lib: HOT2A.concat(HOT2B, HOT2C, HOT2D, HOT2E, HOT2F, HOT2G, HOT2H, HOT2I).map(h => ({ key: h.key, name: h.name, sub: h.sub, deep: false, cat: h.cat, hot: h.hot, profile: h.profile, core: h.core, scenes: h.scenes, real: h.real, vs: h.vs, ids: h.ids.split(" ").filter(Boolean), cks: h.cks.split(" ").filter(Boolean) }))
};

const wikiPath = path.join(dir, "脑机接口功能想象_Wiki.html");
let tpl = fs.readFileSync(wikiPath, "utf8");
const block = "/*DB_START*/\nconst DB=" + JSON.stringify(DB) + ";\n/*DB_END*/";
if (!/\/\*DB_START\*\/[\s\S]*?\/\*DB_END\*\//.test(tpl)) throw new Error("模板缺少 DB 标记");
tpl = tpl.replace(/\/\*DB_START\*\/[\s\S]*?\/\*DB_END\*\//, () => block);
fs.writeFileSync(wikiPath, tpl, "utf8");

console.log("生成完成：items=" + DB.items.length +
  " / groups=" + DB.groups.length +
  " / glossary=" + DB.glossary.length +
  " / works=" + DB.works.length +
  " / hot=" + DB.hot.length +
  " / lib=" + DB.lib.length +
  " / 伦理议题=" + DB.ethics.dims.length +
  " / 风险分布=" + DB.ethics.levels.map(l => l.k + ":" + l.ids.length).join(" ") +
  " / 法律议题=" + DB.law.dims.length +
  " / 法律状态=" + DB.law.levels.map(l => l.k + ":" + l.ids.length).join(" ") +
  " / 不判断=" + DB.law.levels.filter(l => !l.judged).reduce((s, l) => s + l.ids.length, 0) + " 条" +
  " / 平均参见=" + (items.reduce((s, d) => s + d.see.length, 0) / items.length).toFixed(1) +
  " / 输出=" + (Buffer.byteLength(tpl) / 1024).toFixed(1) + " KB");
